torch::Tensor conv3d_kh_kw1_forward(torch::Tensor x,
                                     torch::Tensor w,
                                     c10::optional<torch::Tensor> b,
                                     int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv3d_kh_kw1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int KH, int KW,
    int stride, int padding, int dilation,
    int groups,
    int Hout, int Wout, int Dout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 8;
  constexpr int KChunk     = 32;

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int R = Cin_per_group * KH * KW;
  const int KHW = KH * KW;

  const int tid = threadIdx.x;
  const int n = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int P_total = Hout * Wout * Dout;
  const int PTile = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int64_t sXc = (int64_t)H * Win * D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * (int64_t)Cin * sXc),
      make_shape(Cin, H, Win, D),
      make_stride(sXc, sXh, sXw, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * (int64_t)Cout * sYc),
      make_shape(Cout, Hout, Wout, Dout),
      make_stride(sYc, sYh, sYw, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, R),
      make_stride(R, Int<1>{}));

  __shared__ T sW_raw[CcPerBlock * KChunk];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{}));

  int p_idx[PVec];
  int oh_arr[PVec], ow_arr[PVec], od_arr[PVec];
  int id_arr[PVec];
  bool dvalid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p % Dout;
      int tmp = p / Dout;
      int ow = tmp % Wout;
      int oh = tmp / Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
      od_arr[i] = od;
      int id = od * stride - padding;
      id_arr[i] = id;
      dvalid[i] = (id >= 0 && id < D);
    } else {
      oh_arr[i] = 0; ow_arr[i] = 0; od_arr[i] = 0;
      id_arr[i] = -1; dvalid[i] = false;
    }
  }

  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (Bp != nullptr && c < Cout) bval = (float)Bp[c];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
  }

  for (int r0 = 0; r0 < R; r0 += KChunk) {
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int r_global = r0 + kk;
      #pragma unroll
      for (int cc = 0; cc < CcPerBlock; ++cc) {
        int c = c_base + cc;
        T wval = T(0);
        if (c < Cout && r_global < R) {
          wval = mW(c, r_global);
        }
        sW(cc, kk) = wval;
      }
    }
    __syncthreads();

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      if (!dvalid[i]) continue;

      int oh = oh_arr[i];
      int ow = ow_arr[i];
      int id = id_arr[i];

      #pragma unroll
      for (int kk = 0; kk < KChunk; ++kk) {
        int r_global = r0 + kk;
        if (r_global >= R) break;

        int ic_offset = r_global / KHW;
        int rem = r_global - ic_offset * KHW;
        int kh = rem / KW;
        int kw = rem - kh * KW;

        int ih = oh * stride - padding + kh * dilation;
        if ((unsigned)ih >= (unsigned)H) continue;
        int iw = ow * stride - padding + kw * dilation;
        if ((unsigned)iw >= (unsigned)Win) continue;
        float last_xval = 0.0f;
        int last_group = -1;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int c = c_base + cc;
          if (c >= Cout) continue;
          int g = c / Cout_per_group;
          float xval;
          if (g == last_group) {
            xval = last_xval;
          } else {
            int ic = g * Cin_per_group + ic_offset;
            xval = (float)mX(ic, ih, iw, id);
            last_xval = xval;
            last_group = g;
          }
          float wval = (float)sW(cc, kk);
          acc[cc][i] += xval * wval;
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i], od_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv3d_kh_kw1_forward(torch::Tensor x,
                                     torch::Tensor w,
                                     c10::optional<torch::Tensor> b,
                                     int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, KH, KW, KD]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  int64_t D   = x.size(4);

  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t KH = w.size(2);
  int64_t KW = w.size(3);
  int64_t KD = w.size(4);

  TORCH_CHECK(KD == 1, "This kernel only supports kernel depth (last dim) = 1");
  TORCH_CHECK(Cin_per_group * groups == Cin, "in_channels must be divisible by groups and match weight");
  TORCH_CHECK(Cout % groups == 0, "out_channels must be divisible by groups");

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2*padding - dilation*(KH-1) - 1) / stride + 1;
  int64_t Wout = (Win + 2*padding - dilation*(KW-1) - 1) / stride + 1;
  int64_t Dout = (D + 2*padding - dilation*(KD-1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 8;
  const int64_t P_total = Hout * Wout * Dout;
  const int64_t PTile = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kh_kw1_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)D,
      (int)Cout, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)groups,
      (int)Hout, (int)Wout, (int)Dout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kh_kw1_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_kh_kw1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kh_kw1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with a square kernel over (H, W) and a trivial kernel of size 1
    over the depth dimension, implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        KH = KW = self.kernel_size
        KD = 1
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels // self.groups, KH, KW, KD)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_kh_kw1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

